diff --git a/tests/test_key_shortcuts.py b/tests/test_key_shortcuts.js
--- a/tests/test_key_shortcuts.js
+++ b/tests/test_key_shortcuts.js
@@ -0,0 +1,12 @@
+import { handleKeydown } from "../src/editor/shortcuts";
+
+test("mod+s triggers save", () => {
+  const e = keyEvent("s", { meta: true });
+  const spy = jest.fn();
+  bind("mod+s", spy);
+  handleKeydown(e);
+  expect(spy).toHaveBeenCalled();
+  expect(e.preventDefault).toHaveBeenCalled();
+});
